html, body {
  background: #DD2911;
  color: #FFF;
}
html {
  height: 100%;
  display: flex;
}
body {
  margin: auto;
}
.mario-title {
  font-family: "Open Sans", Helvetica, sans-serif;
  font-weight: 700;
  font-size: 6vw;
  font-size: calc( 100vw / var(--char-total) );
  position: relative;
  padding: 0.4em 0;
  overflow: hidden;
}
.mario-title:after {
  content: "";
  display: block;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  border-bottom: solid 0.2em;
  animation: underline 1s cubic-bezier(0.8, 0, 0, 1);
  animation-fill-mode: both;
}
@keyframes underline {
  from {
    transform: scaleX(0);
  }
}
.mario-title .word {
  display: inline-block;
  animation: slide-up 1.25s cubic-bezier(0.5, 0.2, 0, 1);
  animation-fill-mode: both;
  animation-delay: calc( .5s + (.1s * var(--word-index)) );
}
@keyframes slide-up {
  from {
    transform: translateY(125%);
  }
}
.splitting-mark {
  color: #FFF !important;
}
